'use strict';
let D, metric='acoustic';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=3)=>Number(v).toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d});
const labels={acoustic:'Acoustic composite',lexical:'Lexical composite',total:'Combined composite'};
// Layout helpers and styling follow the full local dashboard. Only aggregate JSON is loaded.
const card=(title,description,body,foot='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2><p class="description">${description}</p></div></div>${body}${foot?`<div class="card-foot">${foot}</div>`:''}</section>`;
const stat=(label,value,hint)=>`<div class="stat"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`;
const table=(headers,body)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
function overview(){return `<div class="stats">${stat('Recording sources','2,003','Includes audio discovered inside archives')}${stat('Nonempty transcripts','1,996','Of 2,000 original transcript rows')}${stat('Retained recordings','1,745','1,098 baseline + 647 follow-up')}${stat('Paired participants','277','Final saved composite-analysis cohort')}</div>
<div class="grid-2">${card('The processing workflow','Python · Librosa · local Whisper · Pandas',`<div class="card-body"><div class="method"><strong>1. Inventory and validate</strong><p>Track recording coverage, missing outputs, and participant/visit matches.</p></div><div class="method"><strong>2. Extract and transcribe</strong><p>Measure pitch, onset, and frame-based perturbation features. Transcribe speech locally with Whisper and derive lexical measures.</p></div><div class="method"><strong>3. Review quality</strong><p>Flag suspicious transcripts and recording measurements. Keep review flags separate from confirmed exclusions.</p></div><div class="method"><strong>4. Compare and communicate</strong><p>Aggregate recordings within participant and visit, compare paired changes, check baseline stress associations, and present saved results in a read-only dashboard.</p></div></div>`)}
${card('Quality checks and coverage','The counts describe different stages and should not be treated as interchangeable.',`<div class="card-body"><div class="coverage-lines"><span>Original acoustic output rows</span><strong>2,000</strong><span>Blank transcript rows</span><strong>4</strong><span>Acoustic rows reporting zero duration</span><strong>4</strong><span>Rows absent from cleaned acoustic outputs</span><strong>255</strong><span>Cleaned baseline recordings checked for decoding</span><strong>1,098</strong><span>Baseline recordings flagged for unusual pitch</span><strong>116</strong></div><p class="metric-description">All cleaned baseline recordings decoded in the waveform audit. A pitch flag is a request for review, not a confirmed exclusion. Missing output rows are coverage gaps, not proof of processing failures.</p></div>`,'A complete reason log for later manual exclusions and a follow-up waveform audit remain outstanding.')}</div>`;}
function forest(){let lo=Math.min(-.3,...D.groups.map(g=>g.metrics[metric].low))-.025,hi=Math.max(.12,...D.groups.map(g=>g.metrics[metric].high))+.025,x=v=>170+(v-lo)/(hi-lo)*440;let ticks=[lo,0,hi];return `<svg class="chart" viewBox="0 0 680 225" role="img" aria-label="Mean within-person changes with 95 percent confidence intervals for three trial arms"><title>${labels[metric]}: follow-up minus baseline</title>${ticks.map(v=>`<line x1="${x(v)}" y1="20" x2="${x(v)}" y2="177" stroke="${v===0?'#9ba5ac':'#edf0ee'}"/><text x="${x(v)}" y="196" text-anchor="middle">${num(v,2)}</text>`).join('')}${D.groups.map((g,i)=>{let v=g.metrics[metric],y=45+i*52;return `<text x="5" y="${y+4}">${esc(g.group)} (n=${g.n})</text><line x1="${x(v.low)}" y1="${y}" x2="${x(v.high)}" y2="${y}" stroke="#355977" stroke-width="2"/><circle cx="${x(v.mean)}" cy="${y}" r="5" fill="#355977"><title>${esc(g.group)}: mean ${num(v.mean)}, 95% interval ${num(v.low)} to ${num(v.high)}</title></circle>`;}).join('')}<text x="390" y="221" text-anchor="middle">Mean change in composite-score units</text></svg>`;}
function findings(){return `<div class="toolbar"><label class="control">Measure<select id="metric">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${metric===k?'selected':''}>${v}</option>`).join('')}</select></label></div>
${card('Before & after by trial arm','Each person contributes one follow-up-minus-baseline change.',`<div class="card-body">${forest()}</div>`,'95% Student t intervals describe the mean within-person change in each arm. They are unadjusted for multiple comparisons. Interval overlap is not a test of differences between arms. Negative values mean a lower composite score, not proven clinical improvement.')}
${card('Group summary',labels[metric],table(['Trial arm','Paired sample','Mean change','95% interval'],D.groups.map(g=>{let v=g.metrics[metric];return `<tr><td>${esc(g.group)}</td><td>${g.n}</td><td>${num(v.mean)}</td><td>${num(v.low)} to ${num(v.high)}</td></tr>`;}).join('')))}
${card('Between-group comparisons','Saved acoustic-composite tests only. Selecting another measure above does not change these tests.',table(['Comparison','Sample sizes','Mean-change difference','p value'],D.comparisons.map(r=>`<tr><td>${esc(r.comparison)}</td><td>${r.n_a} / ${r.n_b}</td><td>${num(r.difference)}</td><td>${num(r.p,4)}</td></tr>`).join('')),'Welch tests on participant changes; unadjusted p-values. Neither intervention-vs-control comparison was statistically significant. No mixed-model ANCOVA has been completed.')}
${card('Baseline associations with perceived stress','A separate sample from the 277-person paired cohort.',table(['Analysis','Sample','Saved finding'],`<tr><td>Acoustic composite vs PSS</td><td>553</td><td>Spearman rho = −0.126; BH-adjusted q = 0.038 across 16 tests</td></tr><tr><td>Separate age/sex-adjusted feature associations</td><td>548</td><td>None of 16 feature coefficients passed BH q &lt; 0.05</td></tr>`),'The weak negative baseline association runs opposite to the acoustic score’s intended direction. The adjusted checks use separate linear models with HC3 errors and a smaller complete-data sample; they are not adjusted versions of the same rank-correlation test.')}`;}
function methods(){return `${card('Engineering contributions','Local processing and a read-only interface for lab review.',`<div class="card-body"><div class="method"><strong>Audio and text processing</strong><p>Librosa acoustic features, local Whisper transcription, transcript checks, and Pandas analysis workflows. The saved full transcription run used whisper-tiny.</p></div><div class="method"><strong>Analysis and quality review</strong><p>Recording inventories, participant/visit reconciliation, feature missingness, paired summaries, baseline questionnaire associations, and waveform-quality review.</p></div><div class="method"><strong>Dashboard</strong><p>Processing coverage, recording warnings, feature distributions, paired comparisons, saved questionnaire associations, and methods. This public page reuses its layout while including only selected broad group summaries.</p></div></div>`)}
${card('How to interpret the measures','The current composites are exploratory.',`<div class="card-body"><div class="method"><strong>Acoustic composite</strong><p>Existing fixed-weight combination: 0.25 × pitch variability + 0.30 × jitter percentage + 0.20 × shimmer percentage + 0.025 × onset rate. I have not fitted or validated these weights against PSS. The inputs have different scales.</p></div><div class="method"><strong>Lexical and combined measures</strong><p>The lexical composite uses sentiment-derived proxies. The combined score uses 0.6 × acoustic + 0.4 × lexical without standardizing them. A change in these scores is not a stress diagnosis.</p></div><div class="method"><strong>Measurement limits</strong><p>The saved jitter and shimmer calculations use frame-level approximations that can span unvoiced gaps. They differ from conventional voice-cycle measurements.</p></div></div>`)}
${card('Open research questions','Measurement definitions, study timing, and validation.',`<ul class="list-clean"><li>Confirm questionnaire timing, speech-task instructions, and usable recording segments with the lab.</li><li>Review feature definitions and document the rationale for score construction.</li><li>Complete follow-up waveform checks and the later exclusion-reason log.</li><li>Obtain any additional health measures and evaluate predictive validity on held-out participants before making predictive claims.</li></ul>`)}
${card('Public-data scope','A fixed summary of saved analyses, not a connection to the private workspace.',`<p class="metric-description">This page includes three broad trial arms, each with at least 54 paired participants, and selected whole-sample findings. It contains no participant rows or aliases, individual chart points, demographic or lifestyle subgroup filters, clinical recordings, transcript text, source paths, or record-level downloads. It makes no requests to the private dashboard. Group-level results remain exploratory research findings.</p>`)} `;}
function render(){const v=['overview','findings','methods'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';const titles={overview:['Processing overview','Audio processing, quality checks, and exploratory findings.'],findings:['Before & after','Real saved results, shown only as broad group summaries.'],methods:['Methods & limitations','Implementation, measurement definitions, and open questions.']};$('#page-title').textContent=titles[v][0];$('#page-subtitle').textContent=titles[v][1];document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===v);if(a.dataset.view===v)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#content').innerHTML=({overview,findings,methods})[v]();$('#metric')?.addEventListener('change',e=>{metric=e.target.value;render();});}
fetch('./summary.json').then(r=>{if(!r.ok)throw Error('Summary unavailable');return r.json();}).then(data=>{D=data;render();window.addEventListener('hashchange',render);}).catch(()=>{$('#content').textContent='The saved summaries could not load. Please reload the page.';});
